/**
 * Loads the static session export (blueprint Step 7). No API, no backend --
 * a single fetched JSON file, per the plan's explicit no-backend contract
 * (FIX-18). Generated by python/scripts/export_web_session.py.
 */
export interface SessionRow {
  t: number;
  mode: string;
  estLat: number;
  estLon: number;
  truthLat: number | null;
  truthLon: number | null;
  speedMs: number;
  headingRad: number;
  radius90m: number | null;
}

export interface Session {
  synthetic: boolean;
  note: string;
  session: string;
  fold: string;
  horizonS: number;
  outageStartS: number;
  outageDurationS: number;
  distanceM: number;
  conformalLambda: number;
  conformalLevel: number;
  refLat: number;
  refLon: number;
  source: string;
  rows: SessionRow[];
}

export async function loadSession(): Promise<Session> {
  const res = await fetch(`${import.meta.env.BASE_URL}data/session.json`);
  if (!res.ok) throw new Error(`failed to load session data: ${res.status}`);
  return (await res.json()) as Session;
}
